import{_ as a,o as n,c as e,aj as s}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20260605212622699.CkxpY7_j.png",m="/assets/image-20260605212636066.DqFA8b4r.png",p="/assets/image-20260605212704827.eECKJJWa.png",o="/assets/image-20260605213224908.DXtfLrVR.png",r="/assets/image-20260605213304278.BJxnYpra.png",l="/assets/image-20260605213350541.DVsVgatT.png",_="/assets/image-20260605213429575.DH3Io8FK.png",c="/assets/image-20260605213459430.srqMbRwo.png",d="/assets/image-20260605213618181.lxb4Pdch.png",g="/assets/image-20260605213825613.BVFgjoIC.png",h="/assets/image-20260605214014357.Ck8w70_6.png",u="/assets/image-20260605214105808.BRY1nLh-.png",K="/assets/image-20260605214121610.BbgRJWc1.png",w="/assets/image-20260404153811993.DCT8eByA.png",P=JSON.parse('{"title":"我把 Kimi 接进微信，几分钟做了个随手出图助手","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/我把 Kimi 接进微信，几分钟做了个随手出图助手/我把 Kimi 接进微信，几分钟做了个随手出图助手.md","filePath":"AI人工智能/我把 Kimi 接进微信，几分钟做了个随手出图助手/我把 Kimi 接进微信，几分钟做了个随手出图助手.md","lastUpdated":1780667323000,"__rawMarkdown":"# 我把 Kimi 接进微信，几分钟做了个随手出图助手\\n\\n## 前言\\n\\n​\\t现在这个网络时代，无论做什么，有一个趁手的出图工具都很重要。比如你发微信朋友圈，或者发小红书，或者做视频封面、写文章配图等等，制作好图片、用好图片，也是一种能力。\\n\\n​\\t结合现在 AI、Kimi Claw 等工具的发展，万少感觉最简单的方式，就是直接像聊天一样给对方发需求，然后对方给你返回图片。\\n\\n![](assets/image-20260605212622699.png)\\n\\n---\\n\\n![](assets/image-20260605212636066.png)\\n\\n---\\n\\n![](assets/image-20260605212704827.png)\\n\\n\\n\\n## 开始吧\\n\\n现在开始尝试几分钟搭建完这一套解决方案。\\n\\n\\n\\n## Kimi Claw\\n\\n​\\t这两天 Kimi 又火了，因为它推出了 Kimi Work，直接对标 Codex 桌面版，用过的人都说像。目前从多模态能力和性价比来看，Kimi 在我心里是第一档。\\n\\n​\\t不过这里万少用的不是 Kimi Work，而是它的前辈 Kimi Claw。Kimi Claw 其实就是 Kimi 推出的“龙虾”产品，方便对接你的聊天工具，比如微信或者飞书，同时又能操作你的电脑。更绝的是，Kimi Claw 自动沿用 Kimi 2.6，而 Kimi 2.6 是多模态的，等于有了眼睛和耳朵，能力确实顶上天了。\\n\\n### 下载 Kimi 桌面端\\n\\n> https://www.kimi.com/?utm_campaign=TR_90K51izQ&utm_content=&utm_medium=%E7%BA%BF%E4%B8%8ACPA&utm_source=CH_AwqiWw8L&utm_term=\\n\\n![](assets/image-20260605213224908.png)\\n\\n### 启动 Kimi Claw\\n\\n在本机电脑上启动 Kimi Claw。\\n\\n![](assets/image-20260605213304278.png)\\n\\n### 连接微信\\n\\n然后点击 **微信** \\n\\n![](assets/image-20260605213350541.png)\\n\\n它会弹出一个二维码，你用微信直接扫。成功之后，你的微信就可以直接使用你电脑上的能力了。\\n\\n![](assets/image-20260605213429575.png)\\n\\n然后你可以简单对话，测试一下。\\n\\n![](assets/image-20260605213459430.png)\\n\\n\\n\\n\\n\\n## 封装一个生图的 skill\\n\\n万少要用这套方案，本质是想做一个随手可出效果图的功能，方便我随时发朋友圈、小红书或者抖音，并且还可以根据我的需求生成图片、视频，甚至文案。请看 prompt：\\n\\n> 帮我封装一个 skill：用来生成适合发布在小红书上的图片或者视频。\\n> 名字是： red-post\\n> 流程：\\n> 1：工作目录是桌面的目录：postDemo\\n> 2：启动终端 “codex --yolo”，其中 Codex 订阅可能会过期。如果过期了，你可以直接使用你 Kimi 的能力帮我处理下面的需求。\\n> 3：根据我提供的文字/图片/视频，加工处理成适合发布在小红书上的形式。因为用户发给你的素材可能来自多次对话，当你准备生成适合发布在小红书上的图片或者视频时，你要和用户确认素材。\\n> 4：加工处理过程要和用户汇报进度。加工处理完后，发送给用户的资料有：图片 + 视频 + 文案。\\n> 以上需求你了解了吗？不理解的话，请和我确认。\\n\\n![](assets/image-20260605213618181.png)\\n\\n后续对话中，我和它不断梳理需求，直到达成一致。\\n\\n需要注意的是，我本来出图是想利用我电脑上的 Codex 来完成。后面想，既然是要图，那就直接接入 GPT-Image2 的能力（*目前最强，有同样需求可以联系我*）。\\n\\n![](assets/image-20260605213825613.png)\\n\\n至此，能力基本完成。\\n\\n因为它是直接在我的电脑上运行的，我想到今天录制的《万少 Claude Code 入门教程》还缺少一些好看的封面图，就直接让它读取我的文件，帮我批量生成了。\\n\\n> 万少 Claude Code 入门教程地址：https://www.bilibili.com/video/BV1AZV16MET5?vd_source=cfc3b9d42efb485bdf45ed50fbf01cf1&spm_id_from=333.788.videopod.sections\\n\\n![](assets/image-20260605214014357.png)\\n\\n*上图中有一些封面图还没有生成*\\n\\n---\\n\\n![](assets/image-20260605214105808.png)\\n\\n---\\n\\n等待一会后，图片也生成出来了，剩下我就可以替换到 B 站合集上。\\n\\n![](assets/image-20260605214121610.png)\\n\\n\\n\\n---\\n\\n最后，以上就是快速搭建这套小工具的解决方案。我总结了一下，这套流程特别适合有推广需求的小伙伴，这样你就可以随手营销自己了。\\n\\n如果过程中有疑问，或者有不懂的地方，欢迎联系万少。此外，也可以加入万少的 AI 交流群，和各行业的小伙伴一起探讨 AI 技术。\\n\\n![](assets/image-20260605214336401.png)\\n"}'),b={name:"AI人工智能/我把 Kimi 接进微信，几分钟做了个随手出图助手/我把 Kimi 接进微信，几分钟做了个随手出图助手.md"};function k(C,i,f,q,A,x){return n(),e("div",null,[...i[0]||(i[0]=[s('<h1 id="我把-kimi-接进微信-几分钟做了个随手出图助手" tabindex="-1">我把 Kimi 接进微信，几分钟做了个随手出图助手 <a class="header-anchor" href="#我把-kimi-接进微信-几分钟做了个随手出图助手" aria-label="Permalink to &quot;我把 Kimi 接进微信，几分钟做了个随手出图助手&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>​ 现在这个网络时代，无论做什么，有一个趁手的出图工具都很重要。比如你发微信朋友圈，或者发小红书，或者做视频封面、写文章配图等等，制作好图片、用好图片，也是一种能力。</p><p>​ 结合现在 AI、Kimi Claw 等工具的发展，万少感觉最简单的方式，就是直接像聊天一样给对方发需求，然后对方给你返回图片。</p><p><img src="'+t+'" alt=""></p><hr><p><img src="'+m+'" alt=""></p><hr><p><img src="'+p+'" alt=""></p><h2 id="开始吧" tabindex="-1">开始吧 <a class="header-anchor" href="#开始吧" aria-label="Permalink to &quot;开始吧&quot;">​</a></h2><p>现在开始尝试几分钟搭建完这一套解决方案。</p><h2 id="kimi-claw" tabindex="-1">Kimi Claw <a class="header-anchor" href="#kimi-claw" aria-label="Permalink to &quot;Kimi Claw&quot;">​</a></h2><p>​ 这两天 Kimi 又火了，因为它推出了 Kimi Work，直接对标 Codex 桌面版，用过的人都说像。目前从多模态能力和性价比来看，Kimi 在我心里是第一档。</p><p>​ 不过这里万少用的不是 Kimi Work，而是它的前辈 Kimi Claw。Kimi Claw 其实就是 Kimi 推出的“龙虾”产品，方便对接你的聊天工具，比如微信或者飞书，同时又能操作你的电脑。更绝的是，Kimi Claw 自动沿用 Kimi 2.6，而 Kimi 2.6 是多模态的，等于有了眼睛和耳朵，能力确实顶上天了。</p><h3 id="下载-kimi-桌面端" tabindex="-1">下载 Kimi 桌面端 <a class="header-anchor" href="#下载-kimi-桌面端" aria-label="Permalink to &quot;下载 Kimi 桌面端&quot;">​</a></h3><blockquote><p><a href="https://www.kimi.com/?utm_campaign=TR_90K51izQ&amp;utm_content=&amp;utm_medium=%E7%BA%BF%E4%B8%8ACPA&amp;utm_source=CH_AwqiWw8L&amp;utm_term=" target="_blank" rel="noreferrer">https://www.kimi.com/?utm_campaign=TR_90K51izQ&amp;utm_content=&amp;utm_medium=线上CPA&amp;utm_source=CH_AwqiWw8L&amp;utm_term=</a></p></blockquote><p><img src="'+o+'" alt=""></p><h3 id="启动-kimi-claw" tabindex="-1">启动 Kimi Claw <a class="header-anchor" href="#启动-kimi-claw" aria-label="Permalink to &quot;启动 Kimi Claw&quot;">​</a></h3><p>在本机电脑上启动 Kimi Claw。</p><p><img src="'+r+'" alt=""></p><h3 id="连接微信" tabindex="-1">连接微信 <a class="header-anchor" href="#连接微信" aria-label="Permalink to &quot;连接微信&quot;">​</a></h3><p>然后点击 <strong>微信</strong></p><p><img src="'+l+'" alt=""></p><p>它会弹出一个二维码，你用微信直接扫。成功之后，你的微信就可以直接使用你电脑上的能力了。</p><p><img src="'+_+'" alt=""></p><p>然后你可以简单对话，测试一下。</p><p><img src="'+c+'" alt=""></p><h2 id="封装一个生图的-skill" tabindex="-1">封装一个生图的 skill <a class="header-anchor" href="#封装一个生图的-skill" aria-label="Permalink to &quot;封装一个生图的 skill&quot;">​</a></h2><p>万少要用这套方案，本质是想做一个随手可出效果图的功能，方便我随时发朋友圈、小红书或者抖音，并且还可以根据我的需求生成图片、视频，甚至文案。请看 prompt：</p><blockquote><p>帮我封装一个 skill：用来生成适合发布在小红书上的图片或者视频。 名字是： red-post 流程： 1：工作目录是桌面的目录：postDemo 2：启动终端 “codex --yolo”，其中 Codex 订阅可能会过期。如果过期了，你可以直接使用你 Kimi 的能力帮我处理下面的需求。 3：根据我提供的文字/图片/视频，加工处理成适合发布在小红书上的形式。因为用户发给你的素材可能来自多次对话，当你准备生成适合发布在小红书上的图片或者视频时，你要和用户确认素材。 4：加工处理过程要和用户汇报进度。加工处理完后，发送给用户的资料有：图片 + 视频 + 文案。 以上需求你了解了吗？不理解的话，请和我确认。</p></blockquote><p><img src="'+d+'" alt=""></p><p>后续对话中，我和它不断梳理需求，直到达成一致。</p><p>需要注意的是，我本来出图是想利用我电脑上的 Codex 来完成。后面想，既然是要图，那就直接接入 GPT-Image2 的能力（<em>目前最强，有同样需求可以联系我</em>）。</p><p><img src="'+g+'" alt=""></p><p>至此，能力基本完成。</p><p>因为它是直接在我的电脑上运行的，我想到今天录制的《万少 Claude Code 入门教程》还缺少一些好看的封面图，就直接让它读取我的文件，帮我批量生成了。</p><blockquote><p>万少 Claude Code 入门教程地址：<a href="https://www.bilibili.com/video/BV1AZV16MET5?vd_source=cfc3b9d42efb485bdf45ed50fbf01cf1&amp;spm_id_from=333.788.videopod.sections" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1AZV16MET5?vd_source=cfc3b9d42efb485bdf45ed50fbf01cf1&amp;spm_id_from=333.788.videopod.sections</a></p></blockquote><p><img src="'+h+'" alt=""></p><p><em>上图中有一些封面图还没有生成</em></p><hr><p><img src="'+u+'" alt=""></p><hr><p>等待一会后，图片也生成出来了，剩下我就可以替换到 B 站合集上。</p><p><img src="'+K+'" alt=""></p><hr><p>最后，以上就是快速搭建这套小工具的解决方案。我总结了一下，这套流程特别适合有推广需求的小伙伴，这样你就可以随手营销自己了。</p><p>如果过程中有疑问，或者有不懂的地方，欢迎联系万少。此外，也可以加入万少的 AI 交流群，和各行业的小伙伴一起探讨 AI 技术。</p><p><img src="'+w+'" alt=""></p>',48)])])}const T=a(b,[["render",k]]);export{P as __pageData,T as default};
